import numpy as np, wave
def rd(p):
    w=wave.open(p); x=np.frombuffer(w.readframes(w.getnframes()),dtype=np.int16).astype(float).reshape(-1,2)
    return x.mean(1)
def track_pitch(x, n=24, win=2048):
    out=[]
    for i in range(n):
        st=int(i*len(x)/n)
        seg=x[st:st+win]
        if len(seg)<win//2 or np.abs(seg).max()<50: out.append(0); continue
        F=np.abs(np.fft.rfft(seg*np.hanning(len(seg)),1<<16)); f=np.fft.rfftfreq(1<<16,1/44100)
        # only consider >50Hz
        m=f>50
        out.append(round(f[np.where(m)[0][np.argmax(F[m])]],1))
    return out
for name in ['fx_arp','fx_pan','fx_volslide','fx_delay','fx_retrig','fx_vib','fx_porta','fx_toneporta','fx_speed','fx_arp2']:
